package notices

type Sender interface { Send(attempt int) int }
type Worker struct{}
func (w *Worker) Send(attempt int) int { return RetryWait(attempt) }
func (w *Worker) Close() bool { return true }
type Preview struct{}
func (p *Preview) Send(attempt int) int { return attempt }
func NoticeKey(value string) string { return value }

